input.command:
cd /tmp && cat > /tmp/mocksrc.ps1 <<'EOF'
function Get-DependencyLicense { param($Name) return $null }
function New-Report {
    param($Names)
    $Names | ForEach-Object {
        $lic = Get-DependencyLicense -Name $_
        [pscustomobject]@{ Name = $_; License = $lic }
    }
}
EOF
cat > /tmp/mock.Tests.ps1 <<'EOF'
BeforeAll { . /tmp/mocksrc.ps1 }
Describe "mock" {
    It "mocks inner function called by outer" {
        Mock Get-DependencyLicense { return "MIT" }
        $r = New-Report -Names @("a","b")
        $r[0].License | Should -Be "MIT"
        Should -Invoke Get-DependencyLicense -Times 2
    }
    It "param-filtered mock" {
        Mock Get-DependencyLicense { "GPL-3.0" } -ParameterFilter { $Name -eq "bad" }
        Mock Get-DependencyLicense { "MIT" } -ParameterFilter { $Name -ne "bad" }
        $r = New-Report -Names @("good","bad")
        ($r | Where-Object Name -eq "bad").License | Should -Be "GPL-3.0"
        ($r | Where-Object Name -eq "good").License | Should -Be "MIT"
    }
}
EOF
pwsh -NoProfile -Command 'Invoke-Pester -Path /tmp/mock.Tests.ps1 -Output Detailed' 2>&1 | tail -25

file.content:
        Rendered        = $rendered
        FailOnViolation = $config.FailOnViolation
    }
}

# ---------------------------------------------------------------------------
# CLI entry point (guarded so dot-sourcing for tests does NOT run it)
# ---------------------------------------------------------------------------

function Invoke-Main {
    param(
        [string]$ConfigPath,
        [string]$ManifestPath,
        [string]$LicenseDbPath,
        [string]$Format,
        [switch]$FailOnViolation
    )

    try {
        $outcome = Invoke-LicenseCheck -ConfigPath $ConfigPath -ManifestPath $ManifestPath `
                       -LicenseDbPath $LicenseDbPath -Format $Format

        Write-Output $outcome.Rendered

        # Emit a markdown summary to the GitHub Actions job summary when available.
        if ($env:GITHUB_STEP_SUMMARY) {
            $md = Format-ComplianceReport -Report $outcome.Report -Format 'Markdown'
            Add-Content -LiteralPath $env:GITHUB_STEP_SUMMARY -Value $md
        }

        $fail = $FailOnViolation.IsPresent -or $outcome.FailOnViolation
        if ($fail -and $outcome.Summary.Denied -gt 0) {
            Write-Error "Compliance check failed: $($outcome.Summary.Denied) denied license(s) found."
            return 1
        }
        return 0
    } catch {
        Write-Error "Dependency license check error: $($_.Exception.Message)"
        return 1
    }
}

# The guard: $MyInvocation.InvocationName is '.' only when the file is being
# dot-sourced. In that case we skip the CLI body so tests get clean functions.
if ($MyInvocation.InvocationName -ne '.') {
    $exitCode = Invoke-Main -ConfigPath $ConfigPath -ManifestPath $ManifestPath `
                    -LicenseDbPath $LicenseDbPath -Format $Format -FailOnViolation:$FailOnViolation
    exit $exitCode
}

